  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01","C02","C03","C04","C05","C12","C14","C19","C24"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01","C02","C03","C04","C05","C12","C14","C19","C24"],
  "claims": [
    {
      "claim": "The query is an indolocarbazole glycoside/lactam structurally closest to LCS1269, for which predicted human intestinal absorption-based bioavailability is greater than 30% (F30% 0.213).",
      "card_ids": ["C19"]
    },
    {
      "claim": "Vinorelbine, a large lipophilic alkaloid, has measured absolute oral bioavailability of 43 ± 14% for the soft-gel capsule in fasted patients (close to 40% by AUCinf) and 36–43% with food; even a liquid-filled capsule gave 25–27%, all above the 20% threshold.",
      "card_ids": ["C02","C04","C05","C12","C14","C24"]
    },
    {
      "claim": "Ondansetron, a carbazole-containing drug, has absolute oral bioavailability of 50–65% in fasted volunteers and remains at 40% after rifampin pretreatment, supporting that this scaffold can achieve F ≥ 20%.",
      "card_ids": ["C01","C03"]
    },
    {
      "claim": "The L5 gut-wall efflux/intestinal metabolism records concern paclitaxel, loperamide, taxane derivatives, and unrelated compounds; none provide query-specific or close-analog evidence, and P-gp efflux mechanism alone is not affirmative evidence for F < 20%.",
      "card_ids": ["C54","C55","C56","C57","C58","C59","C60","C61","C62","C63","C64","C65"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C54","C55","C56","C57","C58","C59","C60","C61","C62","C63","C64","C65"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability data are available for the query molecule itself.",
    "No query-specific gut-wall efflux or intestinal metabolism data are available; L5 records are for paclitaxel, loperamide, taxane derivatives, and unrelated compounds.",
    "The LCS1269 record is a predicted HIA-based value rather than a measured absolute bioavailability.",
    "Vinorelbine bioavailability is formulation-dependent, and the query formulation is unspecified.",
    "First-pass metabolism and systemic clearance of the query are not experimentally characterized.",
    "Query P-gp/CYP3A4 substrate status is not established by any supplied record."
  ],
  "decision_summary": "L5 adds only gut-wall efflux/intestinal metabolism records for paclitaxel, loperamide, and taxane derivatives; none are query-specific or close enough to provide affirmative low-F evidence. The high prediction is retained on the transferable measured/predicted analog evidence (vinorelbine ~40%, ondansetron 50–65%, LCS1269 predicted >30%), with moderate confidence."
}

